-- REM-A7-DOI-SWEEP-1 (2026-10-26, remediation agent rem-a7 fork F4; charter pillars reach and security; agent_issues 100587: fleet-wide sweep of every Zenodo use and DOI reference, owner directive NOZ-DOI-1).
-- Sweep result (scripts/doi-zenodo-inventory.mjs, docs/DOI-ZENODO-INVENTORY.md): the public surfaces read 0 hits, the repository holds 0 emitter candidates, and the data plane of qnfo-audit still carries closed-registry identifiers.
-- This file takes the safe automatic part of the data plane: four legacy display tables that no worker reads or that feed only a generated description. Every changed row is first copied to a bak_noz2_*_20261026 table (the Rollback restores them).
--   * paper_index (620 rows, last synced 2026-07-13): doi on 161 rows (117 '10.5281/..', 3 'https://doi.org/10.5281/..', 40 'CHAPTER-FRAGMENT' markers, 1 test row), zenodo_id on 80, zenodo_url on 1, related_zenodo_ids on 1 -> NULL.
--   * content_entries: doi on 5 publication rows -> NULL; two page sentences (id 9 qnfo-publications, id 11 living-papers) reworded without the registry (the sentence is removed or replaced by what the live pages already say: one stable address per paper).
--   * discovery_projects: doi on 4 rows -> NULL; two description parentheses '(supersedes vN, DOI: 10.5281/..)' and one pending-pipeline phrase reworded.
--   * research_code_libraries.companion_doi on 3 rows -> NULL: pfCodePublish copies it into the description of a new public repository (agent_issues NOZ-DOI-SWEEP-2A carries the code fix and the three existing descriptions).
-- The contract probe of issue 100587 counts exactly the first three tables' fields: 173 before this file (7 + 161 + 5), 0 after. The close evidence is staged only when that count is 0 at apply time; the auto-close trigger closes the issue on the first passing verification.
-- Filed with a doer and a closing probe: NOZ-DOI-SWEEP-2A (fleet-control code task) and NOZ-DOI-SWEEP-2B (QNFO/.github workflow, external-repo-patch). Ledgers and stats tables keyed by closed DOIs are kept (records, join keys; no reader or emitter), see the document.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_index SET doi = (SELECT b.doi FROM bak_noz2_paper_index_20261026 b WHERE b.id = paper_index.id), zenodo_id = (SELECT b.zenodo_id FROM bak_noz2_paper_index_20261026 b WHERE b.id = paper_index.id), zenodo_url = (SELECT b.zenodo_url FROM bak_noz2_paper_index_20261026 b WHERE b.id = paper_index.id), related_zenodo_ids = (SELECT b.related_zenodo_ids FROM bak_noz2_paper_index_20261026 b WHERE b.id = paper_index.id) WHERE id IN (SELECT id FROM bak_noz2_paper_index_20261026); UPDATE content_entries SET doi = (SELECT b.doi FROM bak_noz2_content_entries_20261026 b WHERE b.id = content_entries.id), zenodo_id = (SELECT b.zenodo_id FROM bak_noz2_content_entries_20261026 b WHERE b.id = content_entries.id), body_md = (SELECT b.body_md FROM bak_noz2_content_entries_20261026 b WHERE b.id = content_entries.id) WHERE id IN (SELECT id FROM bak_noz2_content_entries_20261026); UPDATE discovery_projects SET doi = (SELECT b.doi FROM bak_noz2_discovery_projects_20261026 b WHERE b.slug = discovery_projects.slug), description = (SELECT b.description FROM bak_noz2_discovery_projects_20261026 b WHERE b.slug = discovery_projects.slug) WHERE slug IN (SELECT slug FROM bak_noz2_discovery_projects_20261026); UPDATE research_code_libraries SET companion_doi = (SELECT b.companion_doi FROM bak_noz2_research_code_libraries_20261026 b WHERE b.name = research_code_libraries.name) WHERE name IN (SELECT name FROM bak_noz2_research_code_libraries_20261026); UPDATE issue_triage SET close_evidence = NULL WHERE issue_id = 100587 AND close_evidence LIKE 'SWEEP DONE%'; UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:rollback REM-A7-DOI-SWEEP-1' WHERE class = 'fm-code-publish-registry-doi'; INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT a.id, 'rem-a7-rollback', 'closed', 'rem-a7-f4', datetime('now'), 'rolled back by the Rollback line of REM-A7-DOI-SWEEP-1' FROM agent_issues a WHERE (a.title LIKE 'NOZ-DOI-SWEEP-2A:%' OR a.title LIKE 'NOZ-DOI-SWEEP-2B:%') AND a.status = 'open' ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = 'closed', owner = excluded.owner, close_evidence = excluded.close_evidence

CREATE TABLE IF NOT EXISTS bak_noz2_paper_index_20261026 AS SELECT * FROM paper_index WHERE (instr(coalesce(doi, ''), '10.5281') > 0 OR doi IN ('CHAPTER-FRAGMENT', '10.0000/test') OR coalesce(zenodo_id, '') <> '' OR coalesce(zenodo_url, '') <> '' OR coalesce(related_zenodo_ids, '') <> '');
CREATE TABLE IF NOT EXISTS bak_noz2_content_entries_20261026 AS SELECT id, slug, doi, zenodo_id, body_md FROM content_entries WHERE (coalesce(doi, '') <> '' OR coalesce(zenodo_id, '') <> '' OR instr(lower(coalesce(body_md, '')), 'zenodo') > 0 OR instr(lower(coalesce(body_html, '')), 'zenodo') > 0 OR instr(lower(coalesce(abstract, '')), 'zenodo') > 0 OR instr(lower(coalesce(bibliography_json, '')), 'zenodo') > 0 OR instr(lower(coalesce(meta_json, '')), 'zenodo') > 0);
CREATE TABLE IF NOT EXISTS bak_noz2_discovery_projects_20261026 AS SELECT slug, doi, description FROM discovery_projects WHERE (coalesce(doi, '') <> '' OR instr(lower(coalesce(description, '')), 'zenodo') > 0 OR instr(lower(coalesce(features, '')), 'zenodo') > 0 OR instr(coalesce(description, ''), '10.5281') > 0);
CREATE TABLE IF NOT EXISTS bak_noz2_research_code_libraries_20261026 AS SELECT name, companion_doi FROM research_code_libraries WHERE instr(coalesce(companion_doi, ''), '10.5281') > 0;

UPDATE paper_index SET doi = NULL WHERE instr(coalesce(doi, ''), '10.5281') > 0 OR doi IN ('CHAPTER-FRAGMENT', '10.0000/test');
UPDATE paper_index SET zenodo_id = NULL WHERE coalesce(zenodo_id, '') <> '';
UPDATE paper_index SET zenodo_url = NULL WHERE coalesce(zenodo_url, '') <> '';
UPDATE paper_index SET related_zenodo_ids = NULL WHERE coalesce(related_zenodo_ids, '') <> '';
UPDATE content_entries SET doi = NULL WHERE coalesce(doi, '') <> '';
UPDATE content_entries SET zenodo_id = NULL WHERE coalesce(zenodo_id, '') <> '';
UPDATE content_entries SET body_md = replace(body_md, 'All papers receive Zenodo DOIs and IPFS content identifiers for permanent, verifiable storage.', 'All papers receive IPFS content identifiers for permanent, verifiable storage.') WHERE id = 9 AND instr(body_md, 'receive Zenodo DOIs and IPFS') > 0;
UPDATE content_entries SET body_md = replace(body_md, '3. **Zenodo Archiving**: Published papers receive Zenodo DOIs for traditional academic citation.', '3. **Stable addresses**: Every published paper keeps one address at papers.qnfo.org, and new versions keep that address.') WHERE id = 11 AND instr(body_md, '**Zenodo Archiving**') > 0;
UPDATE discovery_projects SET doi = NULL WHERE coalesce(doi, '') <> '';
UPDATE discovery_projects SET description = replace(description, ' (supersedes v2.0, DOI: 10.5281/zenodo.15617573)', ' (supersedes v2.0)') WHERE slug = 'autaxys-master-plan-v3' AND instr(description, '10.5281/zenodo.15617573') > 0;
UPDATE discovery_projects SET description = replace(description, ' (supersedes v1.9, DOI: 10.5281/zenodo.15628365)', ' (supersedes v1.9)') WHERE slug = 'autaxys-unified-framework-v2' AND instr(description, '10.5281/zenodo.15628365') > 0;
UPDATE discovery_projects SET description = replace(description, 'Pending: P4 publication pipeline (Zenodo + Pages deploy).', 'Pending: P4 publication pipeline (Pages deploy).') WHERE slug = 'cfpe-forecast' AND instr(description, 'Zenodo + Pages deploy') > 0;
UPDATE research_code_libraries SET companion_doi = NULL WHERE instr(coalesce(companion_doi, ''), '10.5281') > 0;

UPDATE issue_triage SET close_evidence = 'SWEEP DONE, SAFE REPLACEMENTS APPLIED, REMAINDER FILED (rem-a7 F4, measured 2026-10-26). METHOD: scripts/doi-zenodo-inventory.mjs (new, offline suite) over the tracked files of QNFO/qnfo-workers at 8fb1e92c: 2903 text files scanned, 126 name the registry (829 references: 673 are history records in migrations and handoff documents, 78 owner-authored sources under papers/, 29 guards that filter or refuse the prefix, 25 test fixtures, 7 lines of loop-generated documents, 9 comments, 8 other), 0 emitter candidates; 63 files carry 337 third-party DOIs, which stay (NOZ-DOI-1 amendment). GitHub code search over the QNFO organisation (130 repositories): 1,416 files name the registry; the first 1,000 read gitbook 530, .github 310, qnfo-workers 62, QWAV 53, revolutionary-quantum-guide 18, agentic-ai-deep-tech-research 10, zenodo-automation 7, ultrametric-game-of-life 6, hardware-pathway 4: owner-authored published-paper sources and a retired deposit tool. LIVE SURFACES: 29 URLs (papers.qnfo.org page, API with 200 records, JSON feed, RSS, sitemap, llms.txt, OpenAPI, OAI-PMH Identify and ListRecords; qnfo.org; q08.org; qwav.org and two sub-pages; fleet.qnfo.org and its human API; reading.q08.org; ideas.qnfo.org; mind.q08.org and its entries API; me.q08.org; ask.qwav.tech) read 0 hits for the registry name and for 10.5281; the only DOIs on them are 32 third-party DOIs in mind.q08.org/api/entries.json (stay); living-paper holds 0 registry identifiers on 704 published rows. CHANGED by migrations/2026-10-26-rem-a7-doi-sweep.sql (backups bak_noz2_*_20261026): paper_index 161 doi values (120 registry, 40 CHAPTER-FRAGMENT markers, 1 test row), 80 zenodo_id, 1 zenodo_url, 1 related id list set to NULL; content_entries 5 doi values and 2 page sentences (qnfo-publications, living-papers) reworded without the registry; discovery_projects 4 doi values, 2 description parentheses and 1 pending-pipeline phrase; research_code_libraries.companion_doi 3 values cleared (the source of three public repository descriptions). The contract probe of this issue counts exactly those fields: 173 before, 0 after. NOT CHANGED, with the decision recorded in decision_log (nothing is edited, so there is nothing to revert): owner-authored published-paper sources in GitHub repositories and papers/ (no mass edit of published papers; the public pages read 0), the exit ledger and the stats tables keyed by closed DOIs (zenodo_stats 575, zenodo_exit_ledger 927, zenodo_attribution_audit 573, citation_stats 5,221, impact_scores 124, jnl records 23, paper_revision_log 459, version_queue 60, research_queue 47, social_threads 62, dissemination_tracker 62: records and join keys, no collector or emitter reads them since NOZ-DOI-1), the retired proof ledger. FILED with a doer and a closing probe: NOZ-DOI-SWEEP-2A (three public repository descriptions still carry a closed-registry DOI; fleet-control code task) and NOZ-DOI-SWEEP-2B (QNFO/.github release-pipeline.yml still calls the disabled registry workflow). Full inventory: docs/DOI-ZENODO-INVENTORY.md.'
 WHERE issue_id = 100587 AND coalesce(close_evidence, '') = ''
   AND (SELECT COUNT(*) FROM paper_index WHERE coalesce(doi, '') <> '' OR coalesce(zenodo_id, '') <> '' OR coalesce(zenodo_url, '') <> '' OR coalesce(related_zenodo_ids, '') <> '') = 0 AND (SELECT COUNT(*) FROM content_entries WHERE (coalesce(doi, '') <> '' OR coalesce(zenodo_id, '') <> '' OR instr(lower(coalesce(body_md, '')), 'zenodo') > 0 OR instr(lower(coalesce(body_html, '')), 'zenodo') > 0 OR instr(lower(coalesce(abstract, '')), 'zenodo') > 0 OR instr(lower(coalesce(bibliography_json, '')), 'zenodo') > 0 OR instr(lower(coalesce(meta_json, '')), 'zenodo') > 0)) = 0 AND (SELECT COUNT(*) FROM discovery_projects WHERE (coalesce(doi, '') <> '' OR instr(lower(coalesce(description, '')), 'zenodo') > 0 OR instr(lower(coalesce(features, '')), 'zenodo') > 0 OR instr(coalesce(description, ''), '10.5281') > 0)) = 0;

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'NOZ-DOI-SWEEP-2A: three public repository descriptions carry a closed-registry DOI (QNFO/agentic-collapse, QNFO/ignorance-audit, QNFO/ultrametric-lean)', 'Charter pillar: reach. Found by the 100587 sweep (REM-A7-DOI-SWEEP-1, 2026-10-26). qnfo-fleet-control pfCodePublish (PORTFOLIO-CODE-PUBLISH-1) creates a public repository with the description ''QNFO research code: <name> (companion to <research_code_libraries.companion_doi>). Staged and tested in QNFO/qnfo-workers/<path>.'' and nothing filters a DOI under the closed 10.5281 prefix there (the NO-REGISTRAR-1 guard of the same worker covers the profile README sync only). GitHub read 2026-10-26: QNFO/ignorance-audit, QNFO/ultrametric-lean and QNFO/agentic-collapse each carry one. The D1 source is cleared by migrations/2026-10-26-rem-a7-doi-sweep.sql (research_code_libraries.companion_doi NULL; detector fm-code-publish-registry-doi reads a re-entry), so no new description can pick it up. The three existing descriptions remain: the portfolio loop owns repository descriptions (CLAUDE.md: do not hand-fix them) and its hygiene plan only revises a description it wrote itself or fills an empty one.
Doer: qnfo-fleet-control code loop. (1) pfCodePublish: build the description without a companion DOI that contains 10.5281/ (a third-party DOI may stay). (2) pfHygienePlan and pfHygieneApply: add one action that revises a non-archived repository description that names 10.5281/ to the same text without the parenthesis, through the existing description-revise write path, at most the three repositories per run.
Definition of done: the description of QNFO/ignorance-audit reads exactly ''QNFO research code: ignorance-audit. Staged and tested in QNFO/qnfo-workers/research-code/ignorance-audit.'' (the closing probe reads the GitHub API field; the other two follow the same pattern) and the next daily portfolio sync lists the three without the DOI.
code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js
code-anchor: (row.companion_doi ? " (companion to " + row.companion_doi + ")" : "")', 'claude-session:rem-a7-f4', 'reach', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2A:%');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
SELECT 'issue-' || a.id, a.id, 'the issue names the live public state that its probe reads', 'the doer fixes the defect; the fleet-control tick reads this probe from outside the account and a pass closes the issue', '{"url": "https://api.github.com/repos/QNFO/ignorance-audit", "method": "GET", "check": "json:description", "expected": "QNFO research code: ignorance-audit. Staged and tested in QNFO/qnfo-workers/research-code/ignorance-audit."}', 'external-https', 3, 'qnfo-fleet-control', 1, 'active', 'rem-a7-doi-sweep-v1', 45000, 5, datetime('now')
FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2A:%' AND a.status = 'open';
UPDATE remediation_contracts
   SET verify_probe = '{"url": "https://api.github.com/repos/QNFO/ignorance-audit", "method": "GET", "check": "json:description", "expected": "QNFO research code: ignorance-audit. Staged and tested in QNFO/qnfo-workers/research-code/ignorance-audit."}', verify_transport = 'external-https', status = 'active', last_verdict = NULL, attempts = 0, deferred_since = NULL, module = 'rem-a7-doi-sweep-v1', next_due_at = datetime('now'),
       action = 'the doer fixes the defect; the fleet-control tick reads this probe from outside the account and a pass closes the issue'
 WHERE class = (SELECT 'issue-' || a.id FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2A:%' AND a.status = 'open' ORDER BY a.id DESC LIMIT 1)
   AND coalesce(module, '') <> 'rem-a7-doi-sweep-v1';

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'NOZ-DOI-SWEEP-2B: QNFO/.github release-pipeline.yml still calls the disabled registry workflow and reads its token secrets', 'Charter pillars: reach, security. Found by the 100587 sweep (REM-A7-DOI-SWEEP-1, 2026-10-26). QNFO/.github (default branch master): the workflow ''Zenodo DOI Registration'' (.github/workflows/zenodo-publish.yml) is disabled_manually, but ''Release Pipeline'' (.github/workflows/release-pipeline.yml, state active) still has a job zenodo-publish that uses it (secrets ZENODO_TOKEN and ZENODO_SANDBOX_TOKEN) and two jobs that need its DOI output; its last five runs failed (workflow_dispatch 2026-09-24 08:04Z, 08:09Z, 08:12Z; push 2026-05-25, twice). The staged files of GHA-AUDIT-DOTGITHUB-1 (audits/gha-patches, APPLY.txt) harden the workflow but keep the registry stage.
Doer: the fleet through .github/workflows/external-repo-patch.yml in QNFO/qnfo-workers (repo QNFO/.github, dry mode first, then live; it uses only the repository secret QNFO_GH_PAT). Change: remove the zenodo-publish job and the jobs that need its output from release-pipeline.yml, delete zenodo-publish.yml, keep the PDF and GitBook steps, and add the comment line ''# NOZ-DOI-1: no registry stage'' so the closing probe can read the new file. If QNFO_GH_PAT is refused for workflow files (they need the workflows scope), that single step is IDENTITY-BOUND: an account-level credential only the owner can mint; it then becomes a human_actions card with this probe as its closing probe.
Definition of done: release-pipeline.yml on master carries the marker line (the probe reads the raw file; an error page cannot pass it).', 'claude-session:rem-a7-f4', 'reach', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2B:%');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
SELECT 'issue-' || a.id, a.id, 'the issue names the live public state that its probe reads', 'the doer fixes the defect; the fleet-control tick reads this probe from outside the account and a pass closes the issue', '{"url": "https://raw.githubusercontent.com/QNFO/.github/master/.github/workflows/release-pipeline.yml", "method": "GET", "check": "body-contains:NOZ-DOI-1: no registry stage", "expected": "present"}', 'external-https', 3, 'qnfo-fleet-control', 1, 'active', 'rem-a7-doi-sweep-v1', 45000, 5, datetime('now')
FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2B:%' AND a.status = 'open';
UPDATE remediation_contracts
   SET verify_probe = '{"url": "https://raw.githubusercontent.com/QNFO/.github/master/.github/workflows/release-pipeline.yml", "method": "GET", "check": "body-contains:NOZ-DOI-1: no registry stage", "expected": "present"}', verify_transport = 'external-https', status = 'active', last_verdict = NULL, attempts = 0, deferred_since = NULL, module = 'rem-a7-doi-sweep-v1', next_due_at = datetime('now'),
       action = 'the doer fixes the defect; the fleet-control tick reads this probe from outside the account and a pass closes the issue'
 WHERE class = (SELECT 'issue-' || a.id FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2B:%' AND a.status = 'open' ORDER BY a.id DESC LIMIT 1)
   AND coalesce(module, '') <> 'rem-a7-doi-sweep-v1';

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id)
SELECT 'code-publish-registry-doi',
