  'pfCodePublish (qnfo-fleet-control) copies research_code_libraries.companion_doi into the description of a new public repository and nothing filters the 10.5281 prefix there; the NO-REGISTRAR-1 guard of the same worker covers only the profile README sync',
  'REM-A7-DOI-SWEEP-1: companion_doi cleared in D1 (backup bak_noz2_research_code_libraries_20261026); NOZ-DOI-SWEEP-2A carries the code fix and the three existing descriptions',
  'no research_code_libraries row carries a 10.5281 companion_doi', 'fm-code-publish-registry-doi', '2026-10-26',
  (SELECT a.id FROM agent_issues a WHERE a.title LIKE 'NOZ-DOI-SWEEP-2A:%' ORDER BY a.id DESC LIMIT 1);
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
VALUES ('fm-code-publish-registry-doi', NULL, 'REM-A7-DOI-SWEEP-1 is applied (companion_doi cleared)', 'failure-mode detector: a closed-registry DOI re-entered research_code_libraries.companion_doi, which pfCodePublish copies into a public repository description', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM research_code_libraries WHERE instr(coalesce(companion_doi, ''''), ''10.5281'') > 0) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', 45000, 5, datetime('now'));

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a7-f4',
  'NOZ-DOI-1 (owner directive 2026-10-10, amendment: third-party DOIs stay) is the no-Zenodo, no-DOI directive of the sweep task; a sweep is a reproducible inventory plus the safe replacements, not a mass edit of published papers or of ledgers keyed by closed DOIs',
  'REM-A7-DOI-SWEEP-1: four legacy display tables cleared of closed-registry identifiers with backups, an inventory tool and document added, two successor issues filed (NOZ-DOI-SWEEP-2A and 2B), a re-entry detector added; owner-authored published sources, the exit ledger and the stats tables are kept as records (default recorded here)',
  'public surfaces 0 hits on 29 URLs; repository scan 0 emitter candidates over 2903 files; paper_index 161 doi values, content_entries 5, discovery_projects 4, research_code_libraries 3 closed-registry identifiers; three public repository descriptions and one active workflow still name the registry',
  'applied by migration', 'four tables in qnfo-audit (backups kept), two new issues, one failure mode with a detector, one staged close_evidence; no worker, paper or secret changed',
  'the Rollback line of migrations/2026-10-26-rem-a7-doi-sweep.sql restores every changed row from the bak_noz2 tables',
  'the fleet can re-run the sweep with one command (scripts/doi-zenodo-inventory.mjs) and reads a re-entry of the registry into the code-publish source',
  'the contract probe of issue 100587 reads 0 and closes it; NOZ-DOI-SWEEP-2A and 2B close through their own probes when the code loop and the external-repo-patch workflow have run',
  'reach and security: no public output names the closed registry once the two successor items land',
  'GET of 29 public URLs, 130-repository GitHub code search, org repository metadata and workflow states, a scan of 2903 tracked files, D1 counts per table and column in qnfo-audit and living-paper'
WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.action LIKE 'REM-A7-DOI-SWEEP-1:%');
